-- Conferência ----------------------------------------------------------------
-- Se o livro não fechar com o saldo, o seed falha aqui em vez de deixar o
-- banco silenciosamente errado.
DO $$
DECLARE v_divergentes INT;
BEGIN
  SELECT COUNT(*) INTO v_divergentes FROM vw_conciliacao_estoque WHERE diferenca <> 0;
  IF v_divergentes > 0 THEN
    RAISE EXCEPTION 'Seed inconsistente: % produto(s) com saldo divergente do livro', v_divergentes;
  END IF;
END $$;

ANALYZE;
